      // pause, so the lane never reads PAUSED for a run that cannot resume.
      first = [...seg("hot", "●"), ...plain(" "), ...seg("hot", "STOPPED", true), ...plain(" "), ...seg("mute", "landing"), ...(t0 ? [...DOT, ...seg("mute", duration(now - t0))] : []), ...startedAt("since")];
